    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    if is_matrix:
        # Convert to adjacency list
        adj_list = []
        for i in range(n):
            neighbors = [j for j in range(n) if adj[i][j] == 1]
            adj_list.append(neighbors)
        adj = adj_list
    else:
        # Ensure adjacency list is symmetric and clean
        adj_list = []
        for i in range(n):
            # Remove self-loops and duplicates, ensure valid indices
            neighbors = set()
            for x in adj[i]:
                if isinstance(x, int) and 0 <= x < n and x != i:
                    neighbors.add(x)
            adj_list.append(list(neighbors))
        adj = adj_list

    # Precompute degrees
