            if min_deg >= len(buckets):
                break  # should not happen
            v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            # Remove v
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for u in adj[v]:
                if u in remaining:
                    # remove u from its current bucket
                    old_deg = degree[u]
                    if old_deg < len(buckets) and u in buckets[old_deg]:
                        buckets[old_deg].remove(u)
                    degree[u] -= 1
                    new_deg = degree[u]
                    if new_deg < len(buckets):
                        buckets[new_deg].append(u)
                    # update min_deg if needed
                    if new_deg < min_deg:
                        min_deg = new_deg
        # Reverse order for coloring
        order.reverse()
        return greedy_color(order)

    # Helper: Kempe chain color reduction
    def kempe_reduce(coloring):
        # Make a copy to work on
        col = coloring[:]
        k = max(col) + 1 if n > 0 else 0
        # Try to reduce colors from k-1 downwards
        changed = True
        while changed and k > 1:
            changed = False
            # Target the highest color class
            target_color = k - 1
            vertices = [v for v in range(n) if col[v] == target_color]
            if not vertices:
