                            conflict = True
                            break
                    if not conflict:
                        col[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart from highest color
                # Try Kempe chains
                for c in range(target_color):
                    # Check if v is in a (target_color, c) Kempe chain that can be swapped
                    # We want to see if we can swap a component containing v to free target_color for v
                    # Actually, we want to see if we can recolor v to c via Kempe chain
                    # Standard: if v and some vertex of color c are not connected in the (v_color, c) subgraph, we can swap
                    # But here v has target_color, we want to try to set it to c
                    # So we look at the (target_color, c) subgraph
                    # If v is not connected to any vertex of color c in this subgraph, we can swap the component of v
                    # But easier: try to find if there's a Kempe chain that allows moving v to c
                    # We'll do BFS from v in the subgraph of colors {target_color, c}
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    has_color_c = False
                    while stack:
                        node = stack.pop()
                        if col[node] == c:
                            has_color_c = True
                        for nb in adj[node]:
                            if not visited[nb] and (col[nb] == target_color or col[nb] == c):
                                visited[nb] = True
                                stack.append(nb)
                    # If we found a vertex of color c in the component, swapping would not free c for v
                    # Actually, if the component does NOT contain any vertex of color c, then we can swap
                    # and v will become c
                    if not has_color_c:
                        # Swap colors target_color and c in the component
