                                    col[node] = c
                                elif col[node] == c:
                                    col[node] = target_color
                        col[v] = c  # after swap, v is now c
                        changed = True
                        break
                if changed:
                    break
            if not changed:
                # Could not recolor any vertex in target class, so we need this color
                break
            else:
                # Successfully recolored at least one vertex, check if target color class is empty
                if any(col[v] == target_color for v in range(n)):
                    # Still some vertices with target_color, try again
                    pass
                else:
                    k -= 1
                    changed = True  # continue to try reducing further
        return col

    # Generate candidate colorings
    candidates = []
    # 1. DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # 2. RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # 3. Welsh-Powell
    try:
        c3 = welsh_powell()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass
    # 4. Smallest-Last
    try:
        c4 = smallest_last()
        if is_valid(c4):
