            color[v] = c
        return color

    # Standard DSATUR (vertex-by-vertex) with optimizations and improved tie-breaking
    def dsatur_standard():
        color = [-1] * n
        saturation = [set() for _ in range(n)]
        uncolored = set(range(n))
        neighbor_sets = [set(neighbors) for neighbors in adj_list]

        while uncolored:
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat_v = len(saturation[v])
                if sat_v > max_sat:
                    max_sat = sat_v
                    candidates = [v]
                elif sat_v == max_sat:
                    candidates.append(v)

            if len(candidates) == 1:
                v = candidates[0]
            else:
                max_deg_uncolored = -1
                deg_candidates = []
                for v in candidates:
                    deg_uncolored = len(neighbor_sets[v] & uncolored)
                    if deg_uncolored > max_deg_uncolored:
                        max_deg_uncolored = deg_uncolored
                        deg_candidates = [v]
                    elif deg_uncolored == max_deg_uncolored:
                        deg_candidates.append(v)
                if len(deg_candidates) == 1:
                    v = deg_candidates[0]
                else:
                    min_deg_uncolored = float('inf')
                    final_candidates = []
                    for v in deg_candidates:
                        deg_uncolored = len(neighbor_sets[v] & uncolored)
                        if deg_uncolored < min_deg_uncolored:
                            min_deg_uncolored = deg_uncolored
                            final_candidates = [v]
                        elif deg_uncolored == min_deg_uncolored:
                            final_candidates.append(v)
                    v = random.choice(final_candidates) if final_candidates else random.choice(deg_candidates)

            used_colors = saturation[v]
            c = 0
            while c in used_colors:
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in neighbor_sets[v]:
                if u in uncolored:
                    saturation[u].add(c)

        return color

    # Kempe chain-based color reduction (optimized)
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        max_color = max(coloring) if n > 0 else -1
        if max_color < 0:
            return coloring

        # Try to eliminate color classes from highest to lowest
        for target_color in range(max_color, 0, -1):
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                continue

            eliminated = True
            for v in target_vertices:
                neighbor_colors = set()
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        neighbor_colors.add(coloring[u])
                found = False
                for c in range(target_color):
                    if c not in neighbor_colors:
                        coloring[v] = c
                        found = True
                        break
                if found:
                    continue

                kempe_found = False
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue
                    stack = [v]
                    visited = set([v])
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for u in adj_list[node]:
                            if u not in visited and (coloring[u] == c or coloring[u] == target_color):
                                visited.add(u)
                                stack.append(u)
                    # Check if component is safe to swap
                    safe = True
                    for node in component:
                        if coloring[node] == c:
                            for u in adj_list[node]:
                                if u not in visited and coloring[u] == target_color:
                                    safe = False
                                    break
                            if not safe:
                                break
                        else:  # coloring[node] == target_color
                            for u in adj_list[node]:
                                if u not in visited and coloring[u] == c:
                                    safe = False
                                    break
                            if not safe:
                                break
                    if safe:
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            else:
                                coloring[node] = c
                        kempe_found = True
                        break
                if kempe_found:
                    continue
                eliminated = False
                break
            if eliminated:
                continue
            else:
                break

        return coloring

    # Run all algorithms and pick the best (fewest colors)
    algorithms = [
        ("DSATUR_IndependentSet", dsatur_independent_set),
        ("Welsh-Powell", welsh_powell),
        ("Smallest-Last", smallest_last),
        ("DSATUR_Standard", dsatur_standard)
    ]

    best_coloring = None
    best_num_colors = float('inf')

    for name, algo in algorithms:
        try:
            coloring = algo()
            valid = True
            for u in range(n):
                for v in adj_list[u]:
                    if u < v:
                        if coloring[u] == coloring[v]:
                            valid = False
                            break
                if not valid:
                    break
            if not valid:
                continue
            num_colors = max(coloring) + 1 if n > 0 else 0
            if num_colors < best_num_colors:
                best_num_colors = num_colors
                best_coloring = coloring
        except Exception:
            continue

    if best_coloring is None:
        best_coloring = welsh_powell()
    else:
        try:
            improved = kempe_reduce(best_coloring[:])
            valid = True
            for u in range(n):
                for v in adj_list[u]:
                    if u < v:
                        if improved[u] == improved[v]:
                            valid = False
                            break
                if not valid:
                    break
            if valid:
                num_colors_improved = max(improved) + 1 if n > 0 else 0
                if num_colors_improved < best_num_colors:
                    best_coloring = improved
                    best_num_colors = num_colors_improved
        except Exception:
            pass

    return best_coloring
